const $=id=>document.getElementById(id);
const pupils=[...document.querySelectorAll('.pupil')];
let lastPointer=null;
function trackEyes(event){lastPointer={clientX:event.clientX,clientY:event.clientY};const svg=document.querySelector('.eyes');const matrix=svg.getScreenCTM();if(!matrix)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());for(const eye of pupils){const x=Number(eye.dataset.x),y=Number(eye.dataset.y);const dx=point.x-x,dy=point.y-y;const length=Math.hypot(dx,dy)||1;const strength=Math.min(length/120,1);eye.setAttribute('cx',x+dx/length*4*strength);eye.setAttribute('cy',y+dy/length*2.5*strength);}}
window.addEventListener('pointermove',trackEyes,{passive:true});window.addEventListener('resize',()=>{if(lastPointer)trackEyes(lastPointer);},{passive:true});window.addEventListener('scroll',()=>{if(lastPointer)trackEyes(lastPointer);},{passive:true});document.documentElement.addEventListener('pointerleave',()=>{lastPointer=null;pupils.forEach(p=>{p.setAttribute('cx',p.dataset.x);p.setAttribute('cy',p.dataset.y);});});
$('translate').onclick=()=>{const enabled=$('translate').getAttribute('aria-pressed')!=='true';$('translate').setAttribute('aria-pressed',String(enabled));$('toggle-label').textContent=enabled?'On':'Off';document.body.classList.toggle('translate-on',enabled);$('sign').disabled=!enabled;$('sign').classList.remove('tapped');$('translation').setAttribute('aria-hidden',String(!enabled));$('pyaar').disabled=!enabled;$('pyaar').classList.remove('tapped');$('love').setAttribute('aria-hidden',String(!enabled));};
$('sign').onclick=()=>$('sign').classList.toggle('tapped');$('pyaar').onclick=()=>$('pyaar').classList.toggle('tapped');
let countdownTimer=null;let running=false;let step=0;const stages=['1','2','3','Go!'];
function cancelCountdown(){clearTimeout(countdownTimer);running=false;$('countdown').hidden=true;$('ready').disabled=false;}
let scrollFrame=0;let awake=false;let selectedDrink=-1;
function unlockCafe(){awake=true;document.documentElement.classList.remove('asleep');$('menu').hidden=false;$('menu').inert=false;const button=document.querySelector('[data-page="menu"]');button.disabled=false;button.setAttribute('aria-label','Menu');}
if('scrollRestoration' in history)history.scrollRestoration='manual';window.scrollTo({top:0,behavior:'instant'});
window.addEventListener('pageshow',()=>{if(!awake)window.scrollTo({top:0,behavior:'instant'});});
function go(page){if(page==='menu'&&!awake)return;cancelAnimationFrame(scrollFrame);if(page==='home'){cancelCountdown();}const target=$(page).offsetTop;if(matchMedia('(prefers-reduced-motion: reduce)').matches){window.scrollTo({top:target,behavior:'instant'});return;}const from=window.scrollY,start=performance.now();document.documentElement.classList.add('animating-scroll');function frame(now){const t=Math.min((now-start)/1050,1);let ease;if(t<.7){const q=t/.7;ease=(1-Math.pow(1-q,3))*1.035;}else{const q=(t-.7)/.3;ease=1+.035*Math.cos(q*Math.PI*2)*Math.pow(1-q,2);}window.scrollTo({top:from+(target-from)*ease,behavior:'instant'});if(t<1)scrollFrame=requestAnimationFrame(frame);else{window.scrollTo({top:target,behavior:'instant'});document.documentElement.classList.remove('animating-scroll');}}scrollFrame=requestAnimationFrame(frame);}
$('wake').onclick=()=>{unlockCafe();$('wake').classList.add('clicked');go('menu');};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.page===e.target.id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(e.target.id==='home'&&running)cancelCountdown();}},{threshold:.55});document.querySelectorAll('.screen').forEach(s=>observer.observe(s));
function advance(){if(step<stages.length){$('count').textContent=stages[step++];$('countdown').classList.remove('pulse');void $('countdown').offsetWidth;$('countdown').classList.add('pulse');countdownTimer=setTimeout(advance,900);return;}selectRandomDrink();cancelCountdown();}
function selectRandomDrink(exclude=-1){const options=[...document.querySelectorAll('.menu-list li')];const eligible=options.map((_,i)=>i).filter(i=>i!==exclude);const index=eligible[Math.floor(Math.random()*eligible.length)];selectedDrink=index;options.forEach(li=>{li.classList.remove('selected');['aria-current','tabindex','role','aria-label'].forEach(attr=>li.removeAttribute(attr));});const chosen=options[index];chosen.classList.add('selected');chosen.setAttribute('tabindex','0');chosen.setAttribute('role','button');chosen.setAttribute('aria-label','Make '+chosen.querySelector('h2').textContent.replace(/^\d\. /,''));chosen.setAttribute('aria-current','true');$('result').textContent='Click your highlighted drink to start making it →';$('ready').setAttribute('aria-label','Pick another drink');}
window.pickNextCafeDrink=previous=>{cancelCountdown();selectRandomDrink(previous);go('menu');};
$('ready').onclick=()=>{if(running)return;selectedDrink=-1;running=true;step=0;$('ready').disabled=true;$('result').textContent='';document.querySelectorAll('.menu-list li').forEach(li=>{li.classList.remove('selected');li.removeAttribute('aria-current');li.removeAttribute('tabindex');li.removeAttribute('role');li.removeAttribute('aria-label');});$('countdown').hidden=false;advance();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&running)cancelCountdown();});

document.querySelectorAll('.menu-list li').forEach((li,index)=>{function openDrink(){if(index===selectedDrink&&!running&&window.startCafeRound)window.startCafeRound(index);}li.addEventListener('click',openDrink);li.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDrink();}});});
